package com.mendes.scheduling_platform;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.*; import org.testcontainers.junit.jupiter.*; import org.testcontainers.postgresql.PostgreSQLContainer; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID; import static org.junit.jupiter.api.Assertions.assertThrows;
@Testcontainers(disabledWithoutDocker=true) @SpringBootTest class PostgresIntegrationTest { @Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");@DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}@Autowired JdbcTemplate jdbc;
 @Test void databaseRejectsCrossTenantBookingReferences(){long t1=tenant(),t2=tenant(),venue=venue(t1),customer=customer(t2);OffsetDateTime start=OffsetDateTime.now().plusDays(2);assertThrows(DataIntegrityViolationException.class,()->booking(t1,venue,customer,start,start.plusHours(1)));}
 @Test void databaseRejectsOverlapsAndAllowsAdjacentBookings(){long tenant=tenant(),venue=venue(tenant),customer=customer(tenant);OffsetDateTime start=OffsetDateTime.now().plusDays(3);booking(tenant,venue,customer,start,start.plusHours(1));assertThrows(DataIntegrityViolationException.class,()->booking(tenant,venue,customer,start.plusMinutes(30),start.plusHours(2)));booking(tenant,venue,customer,start.plusHours(1),start.plusHours(2));}
 private long tenant(){return jdbc.queryForObject("INSERT INTO tenants(name,slug,status,plan) VALUES (?,?,?,?) RETURNING id",Long.class,"Tenant",UUID.randomUUID().toString(),"ACTIVE","FREE");}private long venue(long t){return jdbc.queryForObject("INSERT INTO venues(tenant_id,name,type,price,duration_minutes,active) VALUES (?,?,?,?,?,true) RETURNING id",Long.class,t,"Quadra","COURT",BigDecimal.TEN,60);}private long customer(long t){return jdbc.queryForObject("INSERT INTO customers(tenant_id,name,phone) VALUES (?,?,?) RETURNING id",Long.class,t,"Cliente",UUID.randomUUID().toString().substring(0,30));}private void booking(long t,long v,long c,OffsetDateTime start,OffsetDateTime end){jdbc.update("INSERT INTO bookings(tenant_id,venue_id,customer_id,start_date_time,end_date_time,status,total_amount,payment_status) VALUES (?,?,?,?,?,?,?,?)",t,v,c,start,end,"CONFIRMED",BigDecimal.TEN,"PENDING");}}
